package hxdna

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"strings"
	"time"

	"github.com/go-resty/resty/v2"
)

// BootstrapPayload is decoded from the base64 bootstrap token generated by the control plane.
type BootstrapPayload struct {
	URL         string `json:"url"`
	Token       string `json:"token"`
	InstanceID  string `json:"instance_id"`
	OrgID       string `json:"org_id"`
	Environment string `json:"environment"`
	// CA is the private CA (PEM) the control plane's HTTPS and NATS certificates are signed
	// with, when it has no public certificate. Trusted beside the system's authorities, for
	// enrollment and, saved with the State, for every connection after it. Empty = system only.
	CA string `json:"ca"`
}

// EnrollRequest holds the information the worker provides at enrollment time.
type EnrollRequest struct {
	Name        string
	Description string
	Hostname    string
	Version     string
}

// EnrollResult holds the data returned by the control plane after a successful enrollment.
type EnrollResult struct {
	WorkerID   string
	Name       string
	EnrolledAt string
	NatsURL    string
	// SubjectPrefix namespaces this worker's NATS subjects — see State.SubjectPrefix.
	// Required: Enroll returns an error below if the control plane's response omits it.
	SubjectPrefix string
	// NatsKey is this worker's NATS credential — see State.NatsKey. Optional: absent from a
	// control plane that doesn't issue one yet.
	NatsKey string
}

// DecodeBootstrap decodes a base64 bootstrap token into a BootstrapPayload.
func DecodeBootstrap(token string) (*BootstrapPayload, error) {
	raw, err := base64.StdEncoding.DecodeString(token)
	if err != nil {
		raw, err = base64.RawStdEncoding.DecodeString(token)
		if err != nil {
			return nil, fmt.Errorf("invalid bootstrap token: %w", err)
		}
	}
	var bp BootstrapPayload
	if err := json.Unmarshal(raw, &bp); err != nil {
		return nil, fmt.Errorf("malformed bootstrap payload: %w", err)
	}
	return &bp, nil
}

// Enroll registers this worker with the control plane using the decoded bootstrap payload.
func Enroll(bp *BootstrapPayload, req EnrollRequest) (*EnrollResult, error) {
	type requestBody struct {
		Token       string `json:"token"`
		Name        string `json:"name,omitempty"`
		Description string `json:"description,omitempty"`
		Environment string `json:"environment,omitempty"`
		Hostname    string `json:"hostname"`
		Version     string `json:"version"`
	}
	type responseBody struct {
		Data struct {
			WorkerID      string `json:"worker_id"`
			Name          string `json:"name"`
			EnrolledAt    string `json:"enrolled_at"`
			NatsURL       string `json:"nats_url"`
			SubjectPrefix string `json:"subject_prefix"`
			NatsKey       string `json:"nats_key"`
		} `json:"data"`
		Message string `json:"message"`
	}

	body := requestBody{
		Token:       bp.Token,
		Name:        req.Name,
		Description: req.Description,
		Environment: bp.Environment,
		Hostname:    req.Hostname,
		Version:     req.Version,
	}

	client, err := controlClient(bp.CA, 30*time.Second)
	if err != nil {
		return nil, err
	}
	var resp responseBody
	r, err := client.R().
		SetBody(body).
		SetResult(&resp).
		Post(strings.TrimRight(bp.URL, "/") + "/workers/enroll")
	if err != nil {
		return nil, fmt.Errorf("enrollment request failed: %w", err)
	}
	if r.StatusCode() != 200 && r.StatusCode() != 201 {
		return nil, fmt.Errorf("enrollment failed (%d): %s", r.StatusCode(), r.String())
	}
	if resp.Data.WorkerID == "" {
		return nil, fmt.Errorf("control plane returned an empty worker_id — check the bootstrap token and try again")
	}
	if resp.Data.SubjectPrefix == "" {
		return nil, fmt.Errorf("control plane returned an empty subject_prefix — its /workers/enroll response needs updating")
	}
	if !validSubjectPrefix(resp.Data.SubjectPrefix) {
		return nil, fmt.Errorf("control plane returned an invalid subject_prefix %q — must be a single subject token with no \".\", \"*\", \">\", or whitespace", resp.Data.SubjectPrefix)
	}

	return &EnrollResult{
		WorkerID:      resp.Data.WorkerID,
		Name:          resp.Data.Name,
		EnrolledAt:    resp.Data.EnrolledAt,
		NatsURL:       resp.Data.NatsURL,
		SubjectPrefix: resp.Data.SubjectPrefix,
		NatsKey:       resp.Data.NatsKey,
	}, nil
}

// controlClient is an HTTP client for the control plane that also trusts its private CA.
func controlClient(caPEM string, timeout time.Duration) (*resty.Client, error) {
	cfg, err := tlsConfig(caPEM)
	if err != nil {
		return nil, err
	}
	client := resty.New().SetTimeout(timeout)
	if cfg != nil {
		client.SetTLSClientConfig(cfg)
	}
	return client, nil
}

// CheckApproval checks the worker's enrollment status with the control plane.
// Returns "pending", "active", or "revoked".
func CheckApproval(s *State) (string, error) {
	client, err := controlClient(s.CA, 10*time.Second)
	if err != nil {
		return "", err
	}
	var result struct {
		Data struct {
			Status string `json:"status"`
		} `json:"data"`
	}
	resp, err := client.R().
		SetResult(&result).
		Get(strings.TrimRight(s.ControlURL, "/") + "/workers/" + s.WorkerID + "/status")
	if err != nil {
		return "", fmt.Errorf("could not reach control plane: %w", err)
	}
	if resp.StatusCode() == 404 {
		return "", fmt.Errorf("worker not found — re-enroll with: worker enroll <bootstrap>")
	}
	if resp.StatusCode() >= 400 {
		return "", fmt.Errorf("control plane returned %d", resp.StatusCode())
	}
	if result.Data.Status == "" {
		return "", fmt.Errorf("empty status from control plane")
	}
	return result.Data.Status, nil
}
